-- A value in an in-calendar day slot whose day number exceeds NO_DAYS.
-- Run separately with TABLE/PREFIX substitutions DLY_LEVELS/LEVEL and DLY_FLOWS/FLOW.
SELECT COUNT(*) AS rows_with_value_after_no_days
FROM TABLE
WHERE (NO_DAYS < 1 AND PREFIX1 IS NOT NULL) OR (NO_DAYS < 2 AND PREFIX2 IS NOT NULL) OR (NO_DAYS < 3 AND PREFIX3 IS NOT NULL) OR (NO_DAYS < 4 AND PREFIX4 IS NOT NULL) OR (NO_DAYS < 5 AND PREFIX5 IS NOT NULL) OR (NO_DAYS < 6 AND PREFIX6 IS NOT NULL) OR (NO_DAYS < 7 AND PREFIX7 IS NOT NULL) OR (NO_DAYS < 8 AND PREFIX8 IS NOT NULL) OR (NO_DAYS < 9 AND PREFIX9 IS NOT NULL) OR (NO_DAYS < 10 AND PREFIX10 IS NOT NULL) OR (NO_DAYS < 11 AND PREFIX11 IS NOT NULL) OR (NO_DAYS < 12 AND PREFIX12 IS NOT NULL) OR (NO_DAYS < 13 AND PREFIX13 IS NOT NULL) OR (NO_DAYS < 14 AND PREFIX14 IS NOT NULL) OR (NO_DAYS < 15 AND PREFIX15 IS NOT NULL) OR (NO_DAYS < 16 AND PREFIX16 IS NOT NULL) OR (NO_DAYS < 17 AND PREFIX17 IS NOT NULL) OR (NO_DAYS < 18 AND PREFIX18 IS NOT NULL) OR (NO_DAYS < 19 AND PREFIX19 IS NOT NULL) OR (NO_DAYS < 20 AND PREFIX20 IS NOT NULL) OR (NO_DAYS < 21 AND PREFIX21 IS NOT NULL) OR (NO_DAYS < 22 AND PREFIX22 IS NOT NULL) OR (NO_DAYS < 23 AND PREFIX23 IS NOT NULL) OR (NO_DAYS < 24 AND PREFIX24 IS NOT NULL) OR (NO_DAYS < 25 AND PREFIX25 IS NOT NULL) OR (NO_DAYS < 26 AND PREFIX26 IS NOT NULL) OR (NO_DAYS < 27 AND PREFIX27 IS NOT NULL) OR (NO_DAYS < 28 AND PREFIX28 IS NOT NULL) OR (NO_DAYS < 29 AND PREFIX29 IS NOT NULL) OR (NO_DAYS < 30 AND PREFIX30 IS NOT NULL) OR (NO_DAYS < 31 AND PREFIX31 IS NOT NULL);
